contract StubSavings is ISavings {
    SimpleToken public token;
    constructor(SimpleToken _t) { token = _t; }
    function underlying() external view returns (address) { return address(token); }
    function redeemUnderlying(uint256 amount) external returns (uint256) {
        // transfer underlying to caller (the yield source contract)
        token.transfer(msg.sender, amount);
        // BUG: return 0 credits burned (mismatch between savings and imBalances)
        return 0;
    }
