contract MStableYieldSource {
    ISavings public savings;
    SimpleToken public mAsset;
    mapping(address => uint256) public imBalances;
    constructor(ISavings _savings) { savings = _savings; mAsset = SimpleToken(_savings.underlying()); }
    function redeemToken(uint256 mAssetAmount) external returns (uint256 mAssetsActual) {
        uint256 mAssetBalanceBefore = mAsset.balanceOf(address(this));
        uint256 creditsBurned = savings.redeemUnderlying(mAssetAmount);
        imBalances[msg.sender] -= creditsBurned; // vulnerable ordering: relies on savings to burn credits
        uint256 mAssetBalanceAfter = mAsset.balanceOf(address(this));
        mAssetsActual = mAssetBalanceAfter - mAssetBalanceBefore;
        mAsset.transfer(msg.sender, mAssetsActual);
    }
