interface IFootiumClub { function ownerOf(uint256 clubId) external view returns (address); function clubToEscrow(uint256 clubId) external view returns (address); }

contract FootiumPlayer {
    mapping(uint256 => address) public owner;
    uint256 public next;
    function safeMint(address to) external returns (uint256) { next++; owner[next] = to; return next; }
    function ownerOf(uint256 id) external view returns (address) { return owner[id]; }
