contract MaliciousClub {
    address public fixedOwner;
    constructor(address o) { fixedOwner = o; }
    function ownerOf(uint256) external view returns (address) { return fixedOwner; }
    function clubToEscrow(uint256) external view returns (address) { return fixedOwner; }
}

contract FootiumAcademy {
    IFootiumPlayer private _footiumPlayer;
    IFootiumClub private _footiumClub;
    uint256 private _maxGenerationId;
    uint256 public currentSeasonId;
    uint256 public academyMinAge;
    uint256 public academyMaxAge;
    bytes32 private _clubDivsMerkleRoot;
    mapping(SeasonID => mapping(uint256 => mapping(uint256 => bool))) private redeemed;
    mapping(uint256 => uint256) public divisionToFee;
    address private _prizeDistributorAddress;

    constructor(IFootiumPlayer p, IFootiumClub c, address prize) {
        _footiumPlayer = p; _footiumClub = c; _prizeDistributorAddress = prize;
        _maxGenerationId = 100; currentSeasonId = 1; academyMinAge = 18; academyMaxAge = 20; divisionToFee[1] = 0;
    }

    function mintPlayers(
        SeasonID seasonId,
        uint256 clubId,
        uint256 divisionTier,
        uint256[] calldata generationIds,
        bytes32[] calldata divisionProof
    ) external payable {
        uint256 totalFee = _validateMintingParams(seasonId, clubId, divisionTier, generationIds, divisionProof);
        for (uint256 i = 0; i < generationIds.length; i++) {
            uint256 generationId = generationIds[i];
            if (generationId > _maxGenerationId) revert();
            if (redeemed[seasonId][clubId][generationId]) revert();
            redeemed[seasonId][clubId][generationId] = true;
            _footiumPlayer.safeMint(_footiumClub.clubToEscrow(clubId));
        }
        (bool sent, ) = _prizeDistributorAddress.call{value: totalFee}("");
        require(sent || totalFee == 0);
    }

    function _validateMintingParams(
        SeasonID seasonId,
        uint256 clubId,
        uint256 divisionTier,
        uint256[] calldata generationIds,
        bytes32[] calldata divisionProof
    ) private returns (uint256) {
        require(MerkleProofUpgradeable.verify(divisionProof, _clubDivsMerkleRoot, keccak256(abi.encodePacked(clubId, divisionTier))), "not in division");
        require(msg.sender == _footiumClub.ownerOf(clubId), "not club owner");
        require(SeasonID.unwrap(seasonId) > 0, "invalid season");
        require(SeasonID.unwrap(seasonId) <= currentSeasonId, "too young");
        uint256 playerCount = generationIds.length;
        uint256 totalFee = playerCount * divisionToFee[divisionTier];
        require(msg.value >= totalFee, "incorrect eth");
        uint256 maxSeasonId = SeasonID.unwrap(seasonId) + academyMaxAge - academyMinAge;
        require(maxSeasonId >= currentSeasonId, "too old");
        return totalFee;
    }
}

