contract Seal {
    uint256 public today;
    uint256 public spawnRate;
    Token public seal;
    Token public token;
    Pair public cSeal;

    constructor() {
        spawnRate = 1e18;
        seal = new Token();
        token = new Token();
        cSeal = new Pair(seal, token);
    }

    function sealbalance0f(address a) public view returns (uint256) { return seal.balanceOf(a); }

    function getAmountOut(uint256 amountIn, uint256, uint256) public pure returns (uint256) { return amountIn; }

    // Vulnerable: no access control, any external caller can trigger mints/transfers/swaps once per day
    function breed() external {
        require(block.timestamp / 1 days > today);
        today += 1;
        uint256 sealPairAmount = sealbalance0f(address(cSeal));
        uint256 tokenPairAmount = token.balanceOf(address(cSeal));
        uint256 newSeal = sealPairAmount * spawnRate / 1e18;
