contract Quixotic {
    struct SellOrder {
        address payable seller;
        address contractAddress;
        uint256 tokenId;
        uint256 startTime;
        uint256 expiration;
        uint256 price;
        uint256 quantity;
        uint256 createdAtBlockNumber;
        address paymentERC20;
    }

    // Simple cancellation registry stub
    contract CancellationRegistry {
        function getSellOrderCancellationBlockNumber(address, address, uint256) external pure returns (uint256) {
            return 0;
        }
    }

    CancellationRegistry public cancellationRegistry;
    address public lastBuyer;

    constructor() {
        cancellationRegistry = new CancellationRegistry();
    }

    modifier whenNotPaused() { _; }
    modifier nonReentrant() { _; }

    // Vulnerable signature check: note it DOES NOT bind the buyer into the signed data
    function _validateSellerSignature(SellOrder memory order, bytes memory signature) internal pure returns (bool) {
        require(signature.length == 65, "invalid sig length");
        bytes32 digest = keccak256(abi.encodePacked(
            order.seller,
            order.contractAddress,
            order.tokenId,
            order.startTime,
            order.expiration,
            order.price,
            order.quantity,
            order.createdAtBlockNumber,
            order.paymentERC20
        ));
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(signature, 0x20))
            s := mload(add(signature, 0x40))
            v := byte(0, mload(add(signature, 0x60)))
        }
        address recovered = ecrecover(digest, v, r, s);
        return recovered == address(order.seller);
    }

    // Vulnerable function: accepts seller and buyer from caller; only verifies signature that is NOT buyer-bound
    function fillSellOrder(
        address payable seller,
        address contractAddress,
        uint256 tokenId,
        uint256 startTime,
        uint256 expiration,
        uint256 price,
        uint256 quantity,
        uint256 createdAtBlockNumber,
        address paymentERC20,
        bytes memory signature,
        address payable buyer
    ) external payable whenNotPaused nonReentrant {
        if (paymentERC20 == address(0)) {
            require(msg.value >= price, "Transaction doesn't have the required ETH amount.");
        }

        SellOrder memory sellOrder = SellOrder(
            seller,
            contractAddress,
            tokenId,
            startTime,
            expiration,
            price,
            quantity,
            createdAtBlockNumber,
            paymentERC20
        );

        require(
            cancellationRegistry.getSellOrderCancellationBlockNumber(seller, contractAddress, tokenId) < createdAtBlockNumber,
            "This order has been cancelled."
        );

        require(_validateSellerSignature(sellOrder, signature), "Signature is not valid for SellOrder.");

        require((block.timestamp > startTime), "SellOrder start time is in the future.");
        require((block.timestamp < expiration), "This sell order has expired.");

        _fillSellOrder(sellOrder, buyer);
    }

    function _fillSellOrder(SellOrder memory, address buyer) internal {
        // minimal state change to demonstrate exploit
        lastBuyer = buyer;
    }
