        // order params
        address contractAddress = address(1);
        uint256 tokenId = 1;
        uint256 startTime = 0;
        uint256 expiration = block.timestamp + 1000;
        uint256 price = 1 ether;
        uint256 quantity = 1;
        uint256 createdAtBlockNumber = 1;
        address paymentERC20 = address(0);

        // Seller signs an order that does NOT bind the buyer
        bytes32 digest = keccak256(abi.encodePacked(
            payable(seller),
            contractAddress,
            tokenId,
            startTime,
            expiration,
            price,
            quantity,
            createdAtBlockNumber,
