contract FakeRewards {
    MinimalERC20 public gmxBase;
    MinimalERC20 public pxgmx;
    MinimalERC20 public pxglp;
    constructor(address _gmx, address _pxgmx, address _pxglp) {
        gmxBase = MinimalERC20(_gmx);
        pxgmx = MinimalERC20(_pxgmx);
        pxglp = MinimalERC20(_pxglp);
    }
    // claim will mint small amounts to the recipient to simulate rewards
    function claim(address token, address to) external {
        if (token == address(gmxBase)) gmxBase.mint(to, 100);
        else if (token == address(pxgmx)) pxgmx.mint(to, 50);
        else if (token == address(pxglp)) pxglp.mint(to, 200);
    }
}

contract FakePlatform {
    MinimalERC20 public asset;
    constructor(address _asset) { asset = MinimalERC20(_asset); }
    // depositGlp will convert inbound gmxBase into pxGLP (asset) and mint to receiver
    function depositGlp(address, uint256 amount, uint256, uint256, address receiver)
        external
        returns (uint256, uint256, uint256)
    {
        // mint twice the amount to simulate minting pxGLP
        asset.mint(receiver, amount * 2);
        return (0, amount * 2, 0);
    }
}

contract AutoPxGlp {
    address public owner;
    uint256 public platformFee = 1000;
    uint256 public compoundIncentive = 1000;
    address public platform;
    address public rewardsModule;
    MinimalERC20 public gmxBaseReward;
    MinimalERC20 public asset; // pxGLP
    MinimalERC20 public pxGmx;
    uint256 constant FEE_DENOMINATOR = 10000;

    constructor(address _gmx, address _asset, address _pxgmx, address _platform, address _rewards) {
        owner = msg.sender;
        gmxBaseReward = MinimalERC20(_gmx);
        asset = MinimalERC20(_asset);
        pxGmx = MinimalERC20(_pxgmx);
        platform = _platform;
        rewardsModule = _rewards;
    }

    function compound(uint256 minUsdg, uint256 minGlp, bool optOutIncentive)
        public
        returns (uint256 gmxBaseRewardAmountIn, uint256 pxGmxAmountOut, uint256 pxGlpAmountOut, uint256 totalPxGlpFee, uint256 totalPxGmxFee, uint256 pxGlpIncentive, uint256 pxGmxIncentive)
    {
        require(minUsdg != 0 && minGlp != 0, "InvalidParam");
        uint256 preClaimTotalAssets = asset.balanceOf(address(this));
        uint256 preClaimPxGmxAmount = pxGmx.balanceOf(address(this));

        FakeRewards(rewardsModule).claim(address(asset), address(this));
        FakeRewards(rewardsModule).claim(address(pxGmx), address(this));
        FakeRewards(rewardsModule).claim(address(gmxBaseReward), address(this));

        gmxBaseRewardAmountIn = gmxBaseReward.balanceOf(address(this));
        if (gmxBaseRewardAmountIn != 0) {
            (, pxGlpAmountOut, ) = FakePlatform(platform).depositGlp(address(gmxBaseReward), gmxBaseRewardAmountIn, minUsdg, minGlp, address(this));
        }

        uint256 newAssets = asset.balanceOf(address(this)) - preClaimTotalAssets;
        if (newAssets != 0) {
            totalPxGlpFee = (newAssets * platformFee) / FEE_DENOMINATOR;
            pxGlpIncentive = optOutIncentive ? 0 : (totalPxGlpFee * compoundIncentive) / FEE_DENOMINATOR;
            if (pxGlpIncentive != 0) asset.transfer(msg.sender, pxGlpIncentive);
            asset.transfer(owner, totalPxGlpFee - pxGlpIncentive);
        }

        pxGmxAmountOut = pxGmx.balanceOf(address(this)) - preClaimPxGmxAmount;
        if (pxGmxAmountOut != 0) {
            totalPxGmxFee = (pxGmxAmountOut * platformFee) / FEE_DENOMINATOR;
            pxGmxIncentive = optOutIncentive ? 0 : (totalPxGmxFee * compoundIncentive) / FEE_DENOMINATOR;
            if (pxGmxIncentive != 0) pxGmx.transfer(msg.sender, pxGmxIncentive);
            pxGmx.transfer(owner, totalPxGmxFee - pxGmxIncentive);
        }
    }
}

contract AutoPxGlpTest is Test {
    AutoPxGlp target;
    MinimalERC20 gmx;
    MinimalERC20 pxglp;
    MinimalERC20 pxgmx;
    FakeRewards rewards;
    FakePlatform platform;
    address attacker;

    function setUp() public {
        gmx = new MinimalERC20("gmx");
        pxglp = new MinimalERC20("pxglp");
        pxgmx = new MinimalERC20("pxgmx");
        rewards = new FakeRewards(address(gmx), address(pxgmx), address(pxglp));
        platform = new FakePlatform(address(pxglp));
        target = new AutoPxGlp(address(gmx), address(pxglp), address(pxgmx), address(platform), address(rewards));
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_compound() public {
        // attacker calls compound and should receive the pxGLP incentive minted by rewards -> platform
        vm.prank(attacker);
        target.compound(1, 1, false);
        // incentive = (newAssets * platformFee / FEE_DENOMINATOR) * compoundIncentive / FEE_DENOMINATOR
        // rewards minted gmx=100 -> platform minted asset = 200 (amount*2)
        // newAssets = 200 (pxglp minted) + 200 (rewards.claim of pxglp) - pre(0) = 400
        // totalPxGlpFee = 400 * 1000 / 10000 = 40
        // pxGlpIncentive = 40 * 1000 / 10000 = 4
        assertEq(pxglp.balanceOf(attacker), 4);
        // owner (deployer) should receive the remainder of the fee
        assertEq(pxglp.balanceOf(address(this)), 36);
    }
}

