    modifier initializer() {
        require(!_initialized, "initialized");
        _initialized = true;
        _;
    }
}

contract AccessControl {
    mapping(bytes32 => mapping(address => bool)) internal _roles;
    bytes32 public constant DEFAULT_ADMIN_ROLE = bytes32(0);
    modifier onlyRole(bytes32 role) {
        require(hasRole(role, msg.sender), "AccessControl: missing role");
        _;
    }
    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role][account];
    }
    function _setupRole(bytes32 role, address account) internal {
        _roles[role][account] = true;
    }
    function revokeRole(bytes32 role, address account) public {
        _roles[role][account] = false;
    }
}

contract NFTFloorOracle is Initializable, AccessControl {
    bytes32 public constant UPDATER_ROLE = keccak256("UPDATER_ROLE");

    struct OracleConfig { uint128 expirationPeriod; uint128 maxPriceDeviation; }
    OracleConfig public config;

    address[] public feeders;
    address[] public assets;

    struct FeederPosition { bool registered; uint8 index; }
    mapping(address => FeederPosition) private feederPositionMap;
    struct FeederRegistrar { bool registered; uint8 index; bool paused; }
    mapping(address => FeederRegistrar) public assetFeederMap;

    function initialize(address _admin, address[] memory _feeders, address[] memory _assets) public initializer {
        _addAssets(_assets);
        _addFeeders(_feeders);
        _setupRole(DEFAULT_ADMIN_ROLE, _admin);
        _setupRole(UPDATER_ROLE, _admin);
        _setConfig(1800, 150);
    }

    function _addAsset(address _asset) internal {
        require(!assetFeederMap[_asset].registered, "asset existed");
        assetFeederMap[_asset].registered = true;
        assets.push(_asset);
        assetFeederMap[_asset].index = uint8(assets.length - 1);
    }
    function _addAssets(address[] memory _assets) internal {
        for (uint256 i = 0; i < _assets.length; i++) _addAsset(_assets[i]);
    }
    function _addFeeder(address _feeder) internal {
        require(!feederPositionMap[_feeder].registered, "feeder existed");
        feeders.push(_feeder);
        feederPositionMap[_feeder].index = uint8(feeders.length - 1);
        feederPositionMap[_feeder].registered = true;
        _setupRole(UPDATER_ROLE, _feeder);
    }
    function _addFeeders(address[] memory _feeders) internal {
        for (uint256 i = 0; i < _feeders.length; i++) _addFeeder(_feeders[i]);
    }
    function _setConfig(uint128 _expirationPeriod, uint128 _maxPriceDeviation) internal {
        config.expirationPeriod = _expirationPeriod;
        config.maxPriceDeviation = _maxPriceDeviation;
    }

    // privileged function to demonstrate attacker gains DEFAULT_ADMIN_ROLE
    function setConfig(uint128 expirationPeriod, uint128 maxPriceDeviation) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setConfig(expirationPeriod, maxPriceDeviation);
    }
}

contract NFTFloorOracleTest is Test {
