contract NFTFloorOracle {
    bytes32 public constant DEFAULT_ADMIN_ROLE = bytes32(0);
    bytes32 public constant UPDATER_ROLE = keccak256("UPDATER_ROLE");

    // minimal role storage
    mapping(bytes32 => mapping(address => bool)) private _roles;

    // minimal feeders/assets state touched by initialize
    address[] public feeders;
    address[] public assets;

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role][account];
    }

    function _setupRole(bytes32 role, address account) internal {
        _roles[role][account] = true;
    }

    // PUBLIC initializer WITHOUT access control — vulnerability
    function initialize(
        address _admin,
        address[] memory _feeders,
        address[] memory _assets
    ) public {
        // add assets
        for (uint256 i = 0; i < _assets.length; i++) {
            assets.push(_assets[i]);
        }
        // add feeders and grant updater role to them
        for (uint256 i = 0; i < _feeders.length; i++) {
            feeders.push(_feeders[i]);
            _setupRole(UPDATER_ROLE, _feeders[i]);
        }
        // grant admin and updater to provided admin address
        _setupRole(DEFAULT_ADMIN_ROLE, _admin);
        _setupRole(UPDATER_ROLE, _admin);
    }

    modifier onlyRole(bytes32 role) {
        require(hasRole(role, msg.sender), "no role");
        _;
    }

    // admin-only function to demonstrate control after initialize
    function addAssets(address[] calldata _assets) external onlyRole(DEFAULT_ADMIN_ROLE) {
        for (uint256 i = 0; i < _assets.length; i++) assets.push(_assets[i]);
    }
}

contract NFTFloorOracleTest is Test {
    NFTFloorOracle target;
    address attacker;

    function setUp() public {
        target = new NFTFloorOracle();
        attacker = makeAddr("attacker");
