import "forge-std/Test.sol";

// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract NFTFloorOracle {
    struct FeederPosition {
        bool registered;
        uint8 index;
    }

    address[] public feeders;
    mapping(address => FeederPosition) private feederPositionMap;

    bytes32 public constant UPDATER_ROLE = keccak256("UPDATER_ROLE");
    mapping(bytes32 => mapping(address => bool)) private roles;

    function _setupRole(bytes32 role, address account) internal {
        roles[role][account] = true;
    }

    function revokeRole(bytes32 role, address account) internal {
        roles[role][account] = false;
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return roles[role][account];
    }

    // helper for test setup
    function addFeeders(address[] calldata _feeders) public {
        for (uint256 i = 0; i < _feeders.length; i++) {
            _addFeeder(_feeders[i]);
        }
    }

    function _addFeeder(address _feeder) internal {
        feeders.push(_feeder);
        feederPositionMap[_feeder].index = uint8(feeders.length - 1);
        feederPositionMap[_feeder].registered = true;
        _setupRole(UPDATER_ROLE, _feeder);
    }

    function getFeederSize() public view returns (uint256) {
        return feeders.length;
    }

    // Vulnerable: no role check on external remover
    function removeFeeder(address _feeder) external {
        require(feederPositionMap[_feeder].registered, "NFTOracle: feeder not existed");
        _removeFeeder(_feeder);
    }

    function _removeFeeder(address _feeder) internal {
        uint8 feederIndex = feederPositionMap[_feeder].index;
        if (feederIndex >= 0 && feeders[feederIndex] == _feeder) {
            feeders[feederIndex] = feeders[feeders.length - 1];
            feeders.pop();
        }
        delete feederPositionMap[_feeder];
        revokeRole(UPDATER_ROLE, _feeder);
    }
}

contract NFTFloorOracleTest is Test {
    NFTFloorOracle target;
    address attacker;
    address feeder1;
    address feeder2;
    address feeder3;

    function setUp() public {
        target = new NFTFloorOracle();
        attacker = makeAddr("attacker");
        feeder1 = makeAddr("feeder1");
        feeder2 = makeAddr("feeder2");
        feeder3 = makeAddr("feeder3");

        address[] memory initial = new address[](3);
        initial[0] = feeder1;
        initial[1] = feeder2;
        initial[2] = feeder3;
        // setup feeders and give them UPDATER_ROLE
        target.addFeeders(initial);
        // sanity
        assertTrue(target.hasRole(target.UPDATER_ROLE(), feeder1));
        assertEq(target.getFeederSize(), 3);
    }

    function test_attacker_exploits_removeFeeder() public {
        // attacker (no role) removes a legitimate feeder
        vm.prank(attacker);
        target.removeFeeder(feeder1);

        // feeder1 lost UPDATER_ROLE and feeder list shrank
        assertFalse(target.hasRole(target.UPDATER_ROLE(), feeder1));
        assertEq(target.getFeederSize(), 2);
    }
}

